<script setup lang="ts">
import { Boxes, ChevronDown, Download, FileOutput, RefreshCw, ScanText, Square } from "@lucide/vue"
import { computed } from "vue"
import { markdownUrl } from "../api"
import { renderDocumentMarkdown } from "../markdown"
import type { DocumentOutput, DocumentRecord, Job, PageLayout, ParserModel } from "../types"

const props = defineProps<{ document: DocumentRecord; output: DocumentOutput | null; draft: string; job: Job | null; models: ParserModel[]; modelId: string; layoutModels: ParserModel[]; layoutModelId: string; currentLayout: PageLayout | null; blocked: boolean }>()
const emit = defineEmits<{ generate: []; stop: []; "update:modelId": [value: string]; "update:layoutModelId": [value: string] }>()
const active = computed(() => props.job && ["queued", "waiting_for_model", "running"].includes(props.job.state))
const selectedModel = computed(() => props.models.find((model) => model.model_id === props.modelId) ?? null)
const selectedLayoutModel = computed(() => props.layoutModels.find((model) => model.model_id === props.layoutModelId) ?? null)
const canGenerate = computed(() => !props.blocked && Boolean(selectedModel.value?.ready) && (!props.layoutModelId || Boolean(selectedLayoutModel.value?.ready)))
const displayed = computed(() => props.draft || props.output?.content || "")
const html = computed(() => renderDocumentMarkdown(displayed.value))
const progress = computed(() => props.job?.total_units ? Math.round(props.job.completed_units / props.job.total_units * 100) : 0)
function selectModel(event: Event) { emit("update:modelId", (event.target as HTMLSelectElement).value) }
function selectLayoutModel(event: Event) { emit("update:layoutModelId", (event.target as HTMLSelectElement).value) }
const layoutCounts = computed(() => Object.entries(props.currentLayout?.region_counts ?? {}).sort((a, b) => b[1] - a[1]))
</script>

<template>
  <section class="output-tab">
    <header><div><p>MARKDOWN</p><h2>Parsed Document</h2></div><div class="actions"><a v-if="output?.content" :href="markdownUrl(document.id)"><Download :size="15" />Download</a><button v-if="active" class="stop" @click="$emit('stop')"><Square :size="12" fill="currentColor" />Stop</button><button v-else :disabled="!canGenerate" @click="$emit('generate')"><RefreshCw v-if="output?.content" :size="15" /><FileOutput v-else :size="16" />{{ output?.content ? "Regenerate" : "Generate Markdown" }}</button></div></header>
    <div class="model-bar">
      <span class="model-icon"><ScanText :size="16" /></span>
      <div class="model-copy"><strong>OCR model</strong><small>{{ selectedModel?.description || "Choose a local document OCR model" }}</small></div>
      <label class="model-select" :class="{ disabled: active }"><select :value="modelId" :disabled="Boolean(active)" aria-label="OCR model" @change="selectModel"><option v-if="!models.length" value="">No OCR models available</option><option v-for="model in models" :key="model.model_id" :value="model.model_id">{{ model.name }} · {{ model.variant }}{{ model.ready ? "" : " · Setup required" }}</option></select><ChevronDown :size="15" /></label>
      <RouterLink v-if="selectedModel && !selectedModel.ready && !active" class="setup-link" to="/models">Set up</RouterLink>
    </div>
    <div class="model-bar layout-model-bar">
      <span class="model-icon layout-icon"><Boxes :size="16" /></span>
      <div class="model-copy"><strong>Page layout</strong><small>{{ selectedLayoutModel?.description || "OCR the full page without layout guidance" }}</small></div>
      <label class="model-select" :class="{ disabled: active }"><select :value="layoutModelId" :disabled="Boolean(active)" aria-label="Page layout model" @change="selectLayoutModel"><option value="">No layout analysis</option><option v-for="model in layoutModels" :key="model.model_id" :value="model.model_id">{{ model.name }} · {{ model.variant }}{{ model.ready ? "" : " · Setup required" }}</option></select><ChevronDown :size="15" /></label>
      <RouterLink v-if="selectedLayoutModel && !selectedLayoutModel.ready && !active" class="setup-link" to="/models">Set up</RouterLink>
    </div>
    <div v-if="active" class="progress"><div><span>{{ job?.state === "waiting_for_model" ? `Waiting for ${job?.stage === 'waiting_for_layout_model' ? selectedLayoutModel?.name || job?.layout_model_id : selectedModel?.name || job?.model_id}` : `Parsing page ${Math.min((job?.completed_units ?? 0) + 1, job?.total_units ?? document.page_count)} of ${job?.total_units || document.page_count}` }}</span><strong>{{ progress }}%</strong></div><span><i :style="{ width: `${progress}%` }"></i></span></div>
    <div v-if="job?.layout_model_id && currentLayout" class="layout-status" :class="{ failed: currentLayout.error }">
      <div><Boxes :size="15" /><strong>Page {{ currentLayout.display_page }} layout</strong><span v-if="currentLayout.analyzing">Analyzing regions…</span><span v-else-if="currentLayout.error">{{ currentLayout.error }}</span><span v-else-if="currentLayout.current_region">Parsing region {{ currentLayout.current_region.index }} of {{ currentLayout.current_region.total }} · {{ currentLayout.current_region.label }}</span><span v-else>{{ currentLayout.region_count ?? 0 }} regions · reading order ready</span></div>
      <div v-if="layoutCounts.length" class="layout-chips"><span v-for="[label, count] in layoutCounts" :key="label">{{ label }} {{ count }}</span></div>
    </div>
    <div v-if="displayed" class="markdown-body" v-html="html"></div>
    <div v-else class="empty"><FileOutput :size="42" /><h3>No Markdown yet</h3><p>Generate a searchable Markdown version of every page with local OCR.</p></div>
    <aside v-if="output?.warnings.length"><strong>Completed with warnings</strong><p v-for="warning in output.warnings" :key="warning">{{ warning }}</p></aside>
  </section>
</template>

<style scoped>
