ody :deep(li){font-size:.78rem;max-width:100%;overflow-wrap:anywhere;word-break:break-word}.markdown-body :deep(pre){max-width:100%;overflow:auto;white-space:pre-wrap}.markdown-body :deep(code){overflow-wrap:anywhere;white-space:pre-wrap;word-break:break-word}.markdown-body :deep(table){border-collapse:collapse;display:block;max-width:100%;overflow:auto}.markdown-body :deep(td),.markdown-body :deep(th){border:1px solid var(--line);overflow-wrap:anywhere;padding:.4rem;word-break:break-word}.markdown-body :deep(blockquote){border-left:3px solid color-mix(in srgb,var(--accent) 55%,var(--line));color:var(--muted);margin:1rem 0;max-width:100%;padding:.15rem 0 .15rem 1rem}.markdown-body :deep(details){background:color-mix(in srgb,var(--surface-solid) 75%,transparent);border:1px solid var(--line);border-radius:12px;margin:1rem 0;max-width:100%;padding:.7rem .85rem}.markdown-body :deep(summary){cursor:pointer;font-weight:700}.markdown-body :deep(hr){border:0;border-top:1px solid var(--line);margin:1.5rem 0}.markdown-body :deep(img){border-radius:10px;height:auto;max-width:100%}.empty{align-items:center;color:var(--muted);display:flex;flex:1;flex-direction:column;justify-content:center;text-align:center}.empty svg{color:var(--accent)}.empty h3{color:var(--ink);margin:.8rem 0 .25rem}.empty p{font-size:.72rem;max-width:330px}.output-tab aside{background:color-mix(in srgb,#ff9f0a 9%,transparent);border:1px solid color-mix(in srgb,#ff9f0a 30%,var(--line));border-radius:12px;font-size:.65rem;max-width:100%;overflow-wrap:anywhere;padding:.65rem}.output-tab aside p{margin:.25rem 0}
