.layout-model-bar{margin-top:.45rem}.layout-icon{color:#af52de}.layout-status{background:color-mix(in srgb,#af52de 7%,transparent);border:1px solid color-mix(in srgb,#af52de 22%,var(--line));border-radius:13px;margin-top:.55rem;padding:.6rem .7rem}.layout-status>div:first-child{align-items:center;display:flex;gap:.4rem;min-width:0}.layout-status>div:first-child svg{color:#af52de;flex:none}.layout-status strong{font-size:.66rem}.layout-status>div:first-child span{color:var(--muted);font-size:.61rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.layout-status.failed{border-color:color-mix(in srgb,var(--danger) 35%,var(--line))}.layout-chips{display:flex;flex-wrap:wrap;gap:.3rem;margin-top:.45rem}.layout-chips span{background:color-mix(in srgb,#af52de 10%,var(--surface-solid));border:1px solid color-mix(in srgb,#af52de 18%,var(--line));border-radius:999px;color:var(--muted);font-size:.55rem;padding:.2rem .4rem}
